mapper.select:
select u.user_name as userCode, u.nick_name as userName, d.dept_name as deptName, s.semester as semester, s.title as title, pf.teacher_nature as teacherNature, s.total_workload as totalWorkload, s.rated_workload as ratedWorkload, s.excess_workload as excessWorkload, s.is_capped as capped, s.pay_rate as payRate, p.course_hour_pay as coursePay, p.other_pay_total as otherPayTotal, p.total_pay as totalPay, case s.status when 0 then '填报中' when 1 then '待教务审核' when 2 then '已完结' else cast(s.status as char) end as statusLabel from biz_workload_summary s left join biz_pay_record p on p.user_id = s.user_id and p.semester = s.semester left join sys_user u on u.user_id = s.user_id left join sys_dept d on d.dept_id = u.dept_id left join biz_teacher_profile pf on pf.user_id = s.user_id where s.semester = #{semester}
and s.user_id = #{userId}
order by d.dept_id, u.user_name
